/// What's New (src/help.rs): docs/releases/<version>.md copied into OUT_DIR, or an empty
/// file when this version has no notes yet (decision 212).
fn whats_new() {
    let version = std::env::var("CARGO_PKG_VERSION").expect("CARGO_PKG_VERSION");
    let notes = std::path::Path::new("../../docs/releases").join(format!("{version}.md"));
    println!("cargo:rerun-if-changed=../../docs/releases");
    let text = std::fs::read_to_string(&notes).unwrap_or_default();
    let out =
        std::path::Path::new(&std::env::var("OUT_DIR").expect("OUT_DIR")).join("whats_new.md");
    std::fs::write(out, text).expect("write whats_new.md");
}

fn main() {
    whats_new();
    tauri_build::try_build(
        tauri_build::Attributes::new()
            .app_manifest(tauri_build::AppManifest::new().commands(COMMANDS)),
    )
    .expect("failed to run tauri-build");
}
